/*
 * High-performance portfolio calculations using C extension
 *
 * Array inputs are accessed zero-copy through the NumPy C API.  For plain
 * Python sequences (e.g. the list-of-lists produced by the baseline data
 * generator) the C code walks the objects directly, avoiding the expensive
 * creation of a full 2-D NumPy array.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/* Convert an arbitrary Python number-like object to a C double. */
static inline int obj_to_double(PyObject *obj, double *out) {
    if (PyFloat_Check(obj)) {
        *out = PyFloat_AS_DOUBLE(obj);
        return 0;
    }
    {
        double value = PyFloat_AsDouble(obj);
        if (value == -1.0 && PyErr_Occurred())
            return -1;
        *out = value;
        return 0;
    }
}

/* Return a 1-D contiguous double array for any sequence / NumPy array. */
static PyArrayObject *as_double_1d(PyObject *obj) {
    PyArrayObject *arr;

    if (PyArray_Check(obj)) {
        arr = (PyArrayObject *)PyArray_FROM_OTF(
            obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (arr == NULL)
            return NULL;
        if (PyArray_NDIM(arr) != 1) {
            PyErr_SetString(PyExc_ValueError, "expected a 1-D array");
            Py_DECREF(arr);
            return NULL;
        }
        return arr;
    }

    {
        PyObject *seq = PySequence_Fast(obj, "expected a 1-D sequence");
        npy_intp n, i;
        npy_intp dims[1];
        double *dst;

        if (seq == NULL)
            return NULL;

        n = (npy_intp)PySequence_Fast_GET_SIZE(seq);
        dims[0] = n;
        arr = (PyArrayObject *)PyArray_SimpleNew(1, dims, NPY_DOUBLE);
        if (arr == NULL) {
            Py_DECREF(seq);
            return NULL;
        }

        dst = (double *)PyArray_DATA(arr);
        for (i = 0; i < n; ++i) {
            if (obj_to_double(PySequence_Fast_GET_ITEM(seq, i), &dst[i]) < 0) {
                Py_DECREF(seq);
                Py_DECREF(arr);
                return NULL;
            }
        }

        Py_DECREF(seq);
        return arr;
    }
}

/* Return a 2-D contiguous double array for any nested sequence. */
static PyArrayObject *as_double_2d(PyObject *obj) {
    PyArrayObject *arr = NULL;
    PyObject *outer = NULL, *row = NULL;
    npy_intp n, m, i, j;
    npy_intp dims[2];
    double *dst;

    if (PyArray_Check(obj)) {
        arr = (PyArrayObject *)PyArray_FROM_OTF(
            obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (arr == NULL)
            return NULL;
        if (PyArray_NDIM(arr) != 2) {
            PyErr_SetString(PyExc_ValueError, "expected a 2-D array");
            Py_DECREF(arr);
            return NULL;
        }
        return arr;
    }

    outer = PySequence_Fast(obj, "expected a 2-D sequence");
    if (outer == NULL)
        return NULL;
    n = (npy_intp)PySequence_Fast_GET_SIZE(outer);

    if (n == 0) {
        Py_DECREF(outer);
        dims[0] = 0;
        dims[1] = 0;
        return (PyArrayObject *)PyArray_SimpleNew(2, dims, NPY_DOUBLE);
    }

    row = PySequence_Fast(PySequence_Fast_GET_ITEM(outer, 0),
                          "expected each covariance row to be a sequence");
    if (row == NULL)
        goto fail;

    m = (npy_intp)PySequence_Fast_GET_SIZE(row);
    Py_DECREF(row);
    row = NULL;

    dims[0] = n;
    dims[1] = m;
    arr = (PyArrayObject *)PyArray_SimpleNew(2, dims, NPY_DOUBLE);
    if (arr == NULL)
        goto fail;

    dst = (double *)PyArray_DATA(arr);
    for (i = 0; i < n; ++i) {
        row = PySequence_Fast(PySequence_Fast_GET_ITEM(outer, i),
                              "expected each covariance row to be a sequence");
        if (row == NULL)
            goto fail;
        if ((npy_intp)PySequence_Fast_GET_SIZE(row) != m) {
            PyErr_SetString(PyExc_ValueError,
                            "covariance matrix rows have inconsistent lengths");
            goto fail;
        }
        for (j = 0; j < m; ++j) {
            if (obj_to_double(PySequence_Fast_GET_ITEM(row, j),
                              &dst[i * m + j]) < 0)
                goto fail;
        }
        Py_DECREF(row);
        row = NULL;
    }

    Py_DECREF(outer);
    return arr;

fail:
    Py_XDECREF(row);
    Py_XDECREF(outer);
    Py_XDECREF(arr);
    return NULL;
}

static PyObject *portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;
    PyArrayObject *weights = NULL;
    PyArrayObject *cov = NULL;
    double *temp = NULL;
    npy_intp n, i, j;
    double risk_squared = 0.0;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    weights = as_double_1d(weights_obj);
    if (weights == NULL)
        return NULL;
    n = PyArray_DIM(weights, 0);

    /* Fast path: a list of lists of Python floats, avoiding a full copy. */
    if (!PyArray_Check(cov_obj) && PyList_Check(cov_obj) &&
        (npy_intp)PyList_GET_SIZE(cov_obj) == n) {
        int usable = 1;
        for (i = 0; i < n; ++i) {
            PyObject *row = PyList_GET_ITEM(cov_obj, i);
            if (!PyList_Check(row) || (npy_intp)PyList_GET_SIZE(row) != n) {
                usable = 0;
                break;
            }
        }

        if (usable) {
            const double *x = (const double *)PyArray_DATA(weights);

            temp = (double *)malloc((size_t)n * sizeof(double));
            if (temp == NULL) {
                Py_DECREF(weights);
                return PyErr_NoMemory();
            }

            for (i = 0; i < n; ++i) {
                PyObject *row = PyList_GET_ITEM(cov_obj, i);
                double row_sum = 0.0;
                for (j = 0; j < n; ++j) {
                    PyObject *item = PyList_GET_ITEM(row, j);
                    double value;
                    if (PyFloat_Check(item))
                        value = PyFloat_AS_DOUBLE(item);
                    else if (obj_to_double(item, &value) < 0) {
                        free(temp);
                        Py_DECREF(weights);
                        return NULL;
                    }
                    row_sum += value * x[j];
                }
                temp[i] = row_sum;
            }

            for (i = 0; i < n; ++i)
                risk_squared += x[i] * temp[i];

            free(temp);
            Py_DECREF(weights);
            return PyFloat_FromDouble(sqrt(risk_squared));
        }
    }

    /* Generic / NumPy path. */
    cov = as_double_2d(cov_obj);
    if (cov == NULL) {
        Py_DECREF(weights);
        return NULL;
    }

    if (PyArray_DIM(cov, 0) != n || PyArray_DIM(cov, 1) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix dimensions must match weights length");
        Py_DECREF(weights);
        Py_DECREF(cov);
        return NULL;
    }

    {
        const double *x = (const double *)PyArray_DATA(weights);
        const double *S = (const double *)PyArray_DATA(cov);

        temp = (double *)malloc((size_t)n * sizeof(double));
        if (temp == NULL) {
            Py_DECREF(weights);
            Py_DECREF(cov);
            return PyErr_NoMemory();
        }

        for (i = 0; i < n; ++i) {
            const double *row = S + i * n;
            double row_sum = 0.0;
            for (j = 0; j < n; ++j)
                row_sum += row[j] * x[j];
            temp[i] = row_sum;
        }

        for (i = 0; i < n; ++i)
            risk_squared += x[i] * temp[i];
    }

    free(temp);
    Py_DECREF(weights);
    Py_DECREF(cov);

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject *portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;
    PyArrayObject *weights = NULL, *returns = NULL;
    npy_intp n, i;
    double total_return = 0.0;
    const double *x, *r;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    weights = as_double_1d(weights_obj);
    if (weights == NULL)
        return NULL;

    returns = as_double_1d(returns_obj);
    if (returns == NULL) {
        Py_DECREF(weights);
        return NULL;
    }

    n = PyArray_DIM(weights, 0);
    if (PyArray_DIM(returns, 0) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must have the same length");
        Py_DECREF(weights);
        Py_DECREF(returns);
        return NULL;
    }

    x = (const double *)PyArray_DATA(weights);
    r = (const double *)PyArray_DATA(returns);

    for (i = 0; i < n; ++i)
        total_return += x[i] * r[i];

    Py_DECREF(weights);
    Py_DECREF(returns);

    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  /* Initialize NumPy C API */
    return PyModule_Create(&moduledef);
}
